mapper.select:
/* kr.or.kids.domain.cm.community.asmtprp.mapper.selectAsmtPrpSnByAnsSn */
SELECT asmt_prp_sn
  FROM kids_own.tb_cm_m_asmt_prp_ans
 WHERE ans_sn = #{ansSn}

mapper.update:
/* kr.or.kids.domain.cm.community.asmtprp.mapper.updateAsmtPrpAnswer */
UPDATE kids_own.tb_cm_m_asmt_prp_ans


        ans_cn = #{ansCn},



        mdfr_id = #{mdfrId},


    mdfcn_dt = NOW()

WHERE ans_sn = #{ansSn}

/* kr.or.kids.domain.cm.community.asmtprp.mapper.deleteAsmtPrp */
UPDATE kids_own.tb_cm_m_asmt_prp
   SET del_yn = 'Y'
 WHERE asmt_prp_sn = #{asmtPrpSn}

/* kr.or.kids.domain.cm.community.asmtprp.mapper.deleteAsmtPrpAnswer */
UPDATE kids_own.tb_cm_m_asmt_prp_ans
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
 WHERE ans_sn = #{ansSn}

/* kr.or.kids.domain.cm.community.asmtprp.mapper.deleteAnswerByAsmtPrpSn */
UPDATE kids_own.tb_cm_m_asmt_prp_ans
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
 WHERE asmt_prp_sn = #{asmtPrpSn}

/* kr.or.kids.domain.cm.community.asmtprp.mapper.updateAsmtPrpStatusAnswered */
UPDATE kids_own.tb_cm_m_asmt_prp
   SET asmt_prp_ans_stts_cd = '02'
     , mdfcn_dt = NOW()
 WHERE asmt_prp_sn = #{asmtPrpSn}

/* kr.or.kids.domain.cm.community.asmtprp.mapper.updateAsmtPrpStatusWaiting */
UPDATE kids_own.tb_cm_m_asmt_prp
SET asmt_prp_ans_stts_cd = '01'
, mdfcn_dt = NOW()
WHERE asmt_prp_sn = #{asmtPrpSn}

/* kr.or.kids.domain.cm.community.asmtprp.mapper.updateAsmtPrpViewCount */
UPDATE kids_own.tb_cm_m_asmt_prp
   SET pst_inq_cnt = COALESCE(pst_inq_cnt, 0) + 1
     , mdfcn_dt = NOW()
 WHERE asmt_prp_sn = #{asmtPrpSn}
   AND del_yn = 'N'
